import type { Metadata } from "next";
import { Ubuntu_Sans, Hind_Siliguri } from "next/font/google";
import "../globals.css";
import { Providers } from "../providers";
import { Header, Footer, BangladeshMapBackground } from "@/shared/components/layout";
import {
  LOCALES,
  LOCALE_CONFIGS,
  DEFAULT_LOCALE,
  isValidLocale,
  type Locale,
} from "@/shared/i18n/config";

// English / Latin — Ubuntu Sans
const ubuntuSans = Ubuntu_Sans({
  subsets: ["latin"],
  weight: ["400", "500", "600", "700"],
  variable: "--font-ubuntu",
  display: "swap",
});

// Bengali — Hind Siliguri
const hindSiliguri = Hind_Siliguri({
  subsets: ["bengali"],
  weight: ["400", "500", "600", "700"],
  variable: "--font-bengali",
  display: "swap",
});

export const metadata: Metadata = {
  title: "Shelter of Hope | আশ্রয়ের আলো",
  description: "Non-profit humanitarian foundation in Bangladesh",
};

export function generateStaticParams() {
  return LOCALES.map((locale) => ({ locale }));
}

export default async function LocalizedRootLayout({
  children,
  params,
}: {
  children: React.ReactNode;
  params: Promise<{ locale: string }>;
}) {
  const { locale: rawLocale } = await params;
  const locale: Locale = isValidLocale(rawLocale) ? rawLocale : DEFAULT_LOCALE;
  const localeConfig = LOCALE_CONFIGS[locale];

  return (
    <html
      lang={locale}
      className={`${ubuntuSans.variable} ${hindSiliguri.variable} ${localeConfig.htmlClass} h-full antialiased`}
      suppressHydrationWarning
    >
      <body className="min-h-full flex flex-col" suppressHydrationWarning>
        <Providers initialLocale={locale}>
          <Header />
          <BangladeshMapBackground opacity={0.8}>{children}</BangladeshMapBackground>
          <Footer />
        </Providers>
      </body>
    </html>
  );
}

